head.script:
scwin.screenId = "jldfil59400";

///////// 1. 변수 및 선언 영역 /////////

scwin.form = null;


///////// 2. 초기화 영역 /////////

// 런타임 분기 평가 — 공용 $c.util.evalConds (화면은 조건 바인딩 목록만 보유)
// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = function () {
    let binds = [{ id: "if_repIdYn", fn: function(){ return ($c.data.readSessionValue("repIdYn", "session.user.repIdYn") === 'Y'); } }, { id: "if_repIdYn_3", fn: function(){ return ($c.data.readSessionValue("repIdYn", "session.user.repIdYn") === 'N'); } }, { id: "if_repIdYn_2", fn: function(){ return ($c.data.readSessionValue("repIdYn", "session.user.repIdYn") !== 'Y'); } }];
    $c.util.evalConds(binds);
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = function () {
    let __rowCopies = [{ childId: "__rb0", fn: function () { return "전체 " + String($c.data.readValue("dma_page", "total", { silent: true })) + "건 [" + String($c.data.readValue("dma_page", "currentPage", { silent: true })) + "/" + String($c.data.readValue("dma_page", "pageCount", { silent: true })) + " Page] "; } }];
    $c.data.copyRows(__rowCopies);
};

/**
 * @method
 * @name scwin.initPageIndex
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.initPageIndex = async function () {
    $c.util.getComponent('dma_viewDetailReq').set('pageIndex', 1);
    await scwin.fn_Search();
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        scwin.form = (document.searchForm || { elements: [] });
        if (scwin.returnVal === "N") {
            await $c.win.alert('처리 중 오류가 발생하였습니다. 시스템 관리자에게 문의하여 주세요.');
        } else {
            if (scwin.loadTp === "5") {
                await $c.win.alert('제출 처리되었습니다.');
            } else {
                if (scwin.loadTp === "6") {
                    await $c.win.alert('수정요청 처리되었습니다.');
                } else {
                    if (scwin.loadTp === "7") {
                        await $c.win.alert('철회 처리되었습니다.');
                    } else {
                        if (scwin.loadTp === "4") {
                            await $c.win.alert('삭제 처리되었습니다.');
                        }
                    }
                }
            }
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil59400.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)
/**
 * @method
 * @name scwin.init_sessionFill
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_sessionFill = function () {
    let names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil59400' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            let token = '${session.user.' + names[i] + '}';
            let __r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); __r0 = __r0.body || __r0; let __doc = __r0.ownerDocument || __r0; let w = __doc.createTreeWalker(__r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            let ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { $c.data.recvParamData('dma_pageContext'); };

scwin.loadTp = String(($c.data.readValue("dma_pageContext", "loadTp", { ctx: true, soft: true, label: "loadTp" })) == null ? '' : ($c.data.readValue("dma_pageContext", "loadTp", { ctx: true, soft: true, label: "loadTp" }))).indexOf('$' + '{') >= 0 ? '' : String(($c.data.readValue("dma_pageContext", "loadTp", { ctx: true, soft: true, label: "loadTp" })) == null ? '' : ($c.data.readValue("dma_pageContext", "loadTp", { ctx: true, soft: true, label: "loadTp" })));

scwin.returnVal = String(($c.data.readValue("dma_pageContext", "returnVal", { ctx: true, soft: true, label: "returnVal" })) == null ? '' : ($c.data.readValue("dma_pageContext", "returnVal", { ctx: true, soft: true, label: "returnVal" }))).indexOf('$' + '{') >= 0 ? '' : String(($c.data.readValue("dma_pageContext", "returnVal", { ctx: true, soft: true, label: "returnVal" })) == null ? '' : ($c.data.readValue("dma_pageContext", "returnVal", { ctx: true, soft: true, label: "returnVal" })));

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil59400.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.slc_pageSize_onchange
 * @author Inswave
 * @date 2026. 09. 06
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_pageSize_onchange = async function(e){
    try { let ev = e; let event = ev; let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this; await scwin.initPageIndex() 
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil59400.slc_pageSize_onchange' }); }
};

/**
 * @event
 * @name scwin.grd_pageList_oncellclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) { try { let dl = $c.util.getComponent('dlt_pageList'); let r = dl && dl.getRowJSON ? dl.getRowJSON(rowIndex) : null; if (!r) { return; } if (columnId === "__rowAct") { if (r["listProcsStatCd"] === '33' || r["listProcsStatCd"] === '36') { scwin.fn_AdjReqPop(r["bzProcsNo"], "210", "80"); return; } if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { await scwin.fn_EditStatus(r["bzProcsNo"], "applSubmit", "제출"); return; } return; } if (r["listProcsStatCd"] !== '30' && r["listProcsStatCd"] !== '37' && r["listProcsStatCd"] !== '35') { await scwin.viewDetail(r["bzProcsNo"], "8"); return; } if (r["listProcsStatCd"] === '30') { await scwin.viewDetail(r["bzProcsNo"], "1"); return; } if (r["listProcsStatCd"] === '35') { await scwin.viewDetail(r["bzProcsNo"], "1"); return; } if (r["listProcsStatCd"] === '37') { await scwin.viewDetail(r["bzProcsNo"], "1"); return; } await scwin.viewDetail(r["bzProcsNo"], "9"); return; } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' }); } };

/**
 * @event
 * @name scwin.btn_newWrite_onclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_newWrite_onclick = function(e){
    try { let ev = e; let event = ev; let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this; scwin.newWrite() 
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil59400.btn_newWrite_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_viewDetail
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_viewDetail = async function () {
    const sbmOptions = {
        id: "tx_viewDetail",
        method: "post",
        action: "/listInvstg/specyValuAppl.do",
        ref: "dma_viewDetailReq",
        target: "dlt_pageList=body",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldfil59400.tx_viewDetail" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};

/**
 * @method
 * @name scwin.tx_fn_Search
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/listInvstg/specyValuAppl.do",
        ref: "dma_SearchReq",
        target: "dlt_pageList=body",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldfil59400.tx_fn_Search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};

/**
 * @method
 * @name scwin.tx_fn_EditStatus
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_EditStatus = async function () {
    const sbmOptions = {
        id: "tx_fn_EditStatus",
        method: "post",
        action: "/listInvstg/specyValuAppl.do",
        ref: "dma_EditStatusReq",
        target: "dlt_pageList=body",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldfil59400.tx_fn_EditStatus" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @event
 * @name scwin.grd_pageList_fillAct
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.grd_pageList_fillAct = async function () { try { let dl = $c.util.getComponent('dlt_pageList'); if (!dl || !dl.getTotalRow) { return; } for (let i = 0; i < dl.getTotalRow(); i++) { let r = dl.getRowJSON(i); let v = '-'; if (r) { if (r["listProcsStatCd"] === '33' || r["listProcsStatCd"] === '36') { v = "수정요청"; } else if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { v = "제출"; } } dl.setCellData(i, "__rowAct", v); } } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.fillAct' }); } };

/**
 * @method
 * @name scwin.viewDetail
 * @author Inswave
 * @date 2026. 09. 06
 * @param bzProcsNo strLoadTp
 * @returns
 * @hidden N
*/
scwin.viewDetail = async function (bzProcsNo, strLoadTp) {
    $c.util.getComponent('dma_viewDetailReq').set('bzProcsNo', bzProcsNo);
    scwin.form.action = '/listInvstg/specyValuAppl.do';
    $c.util.getComponent('dma_viewDetailReq').set('method', 'editForm');
    $c.util.getComponent('dma_viewDetailReq').set('loadTp', strLoadTp);
    await scwin.tx_viewDetail();
};


/**
 * @method
 * @name scwin.newWrite
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.newWrite = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil59410/jldfil59410.xml');
};


/**
 * @method
 * @name scwin.fn_Search
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_Search = async function () {
    scwin.form.action = "/listInvstg/specyValuAppl.do";
    await scwin.tx_fn_Search();
};


/**
 * @method
 * @name scwin.fn_EditStatus
 * @author Inswave
 * @date 2026. 09. 06
 * @param bzProcsNo strMethod strMsg
 * @returns
 * @hidden N
*/
scwin.fn_EditStatus = async function (bzProcsNo, strMethod, strMsg) {
    scwin.form.action = "/listInvstg/specyValuAppl.do";
    $c.util.getComponent('dma_viewDetailReq').set('method', strMethod);
    $c.util.getComponent('dma_viewDetailReq').set('bzProcsNo', bzProcsNo);
    if (await $c.win.confirm(strMsg + '하시겠습니까?')) {
        await scwin.tx_fn_EditStatus();
    }
};


/**
 * @method
 * @name scwin.fn_AdjReqPop
 * @author Inswave
 * @date 2026. 09. 06
 * @param bzProcsNo listInvstgBzTpCd listBzDtlTpCd
 * @returns
 * @hidden N
*/
scwin.fn_AdjReqPop = async function (bzProcsNo, listInvstgBzTpCd, listBzDtlTpCd) {
    w = '500';
    h = '250';
    l = screen.width / 2 - w / 2;
    t = screen.height / 2 - h / 2;
    let corpSearchURL = '/jldfil59410/jldfil59410.xml';
    await $c.win.openPopup(corpSearchURL, { id: "AdjReqPop", scrollbars: false, resizable: false, width: "500", height: "250", type: "pageFramePopup" }, { method: "selectAvailableAdjReq", bzProcsNo: bzProcsNo, listInvstgBzTpCd: listInvstgBzTpCd, listBzDtlTpCd: listBzDtlTpCd });
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_82_onclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_82_onclick = function (index) { try { $c.util.getComponent('dma_viewDetailReq').set('pageIndex', index); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_82.page' }); } scwin.fn_Search(); };
